<# 
The code below is part of the USS-SCT-Periodic Restart Required GPO, put directly in the scheduled task action parameters.
RestartAlertDays - Number of days since the last restart (not shutdown) before invoking the forced restart.
LastRunWaitHours - Number of hours to wait before attempting to give another restart prompt (in case it got cleared or errored).
LastRunFile - The filepath that will contain the date of the last time the restart was attempted.
LastRestartFile - The filepath that will contain the date of the last time the restart was successfully prompted.

-NoProfile -WindowStyle Hidden -command "$RestartAlertDays = 7; $LastRunWaitHours = 24; $LastRunFile='C:\TEMP\RestartReminderLastRun'; $LastRestartFile = 'C:\TEMP\LastRestartPrompt'; $uptimeDays = ((Get-Date) - (Get-CimInstance -Class Win32_OperatingSystem -Property LastBootUpTime | Select -ExpandProperty LastBootUpTime)).Days; if ($uptimeDays -is [int] -And $uptimeDays -ge $RestartAlertDays) { $doProcess = $true; try { if ((Test-Path $LastRunFile -PathType Leaf)) { $lastRunDate = (Get-Content $LastRunFile -ea Stop) -as [datetime]; if ($lastRunDate -is [datetime] -And ((Get-Date) - $lastRunDate).TotalHours -le $LastRunWaitHours) { $doProcess = $false } } } catch { Write-Error $_; $doProcess = $false }; if ($doProcess) { try { $regpath = 'HKLM:\SOFTWARE\Microsoft\SMS\Mobile Client\Reboot Management\RebootData'; New-ItemProperty -LiteralPath $regpath -Name 'RebootBy' -Value ([DateTimeOffset]::Now.ToUnixTimeSeconds()) -PropertyType QWord -Force -ea SilentlyContinue; New-ItemProperty -LiteralPath $regpath -Name 'RebootValueInUTC' -Value 1 -PropertyType DWord -Force -ea SilentlyContinue; New-ItemProperty -LiteralPath $regpath -Name 'NotifyUI' -Value 1 -PropertyType DWord -Force -ea SilentlyContinue; New-ItemProperty -LiteralPath $regpath -Name 'HardReboot' -Value 0 -PropertyType DWord -Force -ea SilentlyContinue; New-ItemProperty -LiteralPath $regpath -Name 'OverrideRebootWindowTime' -Value 0 -PropertyType QWord -Force -ea SilentlyContinue; New-ItemProperty -LiteralPath $regpath -Name 'OverrideRebootWindow' -Value 0 -PropertyType DWord -Force -ea SilentlyContinue; New-ItemProperty -LiteralPath $regpath -Name 'PreferredRebootWindowTypes' -Value @('4') -PropertyType MultiString -Force -ea SilentlyContinue; New-ItemProperty -LiteralPath $regpath -Name 'GraceSeconds' -Value 0 -PropertyType DWord -Force -ea SilentlyContinue; Restart-Service ccmexec -force; Set-Content -Path $LastRestartFile -Value (Get-Date); } catch { Write-Error $_ } }; Set-Content -Path $LastRunFile -Value (Get-Date); }"
#>